window.HOEREN_TESTS[47] = {"id":"im-supermarkt","name":"Im Supermarkt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden des Supermarktes EDEKA: Wir haben heute Sonderangebote. Tomaten kosten nur 1 Euro pro Kilo, Äpfel 1 Euro 50 und Kartoffeln 80 Cent. Bananen sind heute leider nicht im Angebot, die kommen erst morgen wieder. Die Sonderangebote gelten nur bis zum Ladenschluss. Wir wünschen Ihnen einen guten Einkauf!","gender":"f","q":"Was ist nicht im Angebot?","opts":["Tomaten.","Kartoffeln.","Bananen."],"correct":2},{"transcript":"Hallo Lisa, hier ist Anna. Kannst du bitte auf dem Heimweg im Supermarkt vorbei? Wir brauchen Milch, Brot und Butter. Käse haben wir noch genug, und Joghurt auch. Aber die Eier sind alle. Also bitte Milch, Brot, Butter und Eier kaufen. Das Geld liegt in der Küche. Danke und bis später!","gender":"f","q":"Was muss Lisa kaufen?","opts":["Käse.","Eier.","Joghurt."],"correct":1},{"transcript":"Achtung Kunden: Die Kassen 1, 3 und 5 sind ab heute Selbstbedienungs-Kassen. Wer einen kleinen Einkauf hat, kann dort selbst scannen. Früher gab es nur eine solche Kasse, jetzt sind es drei. Kassen 2, 4 und 6 bleiben normal mit Personal, also nicht alle sechs. Bezahlen können Sie überall mit Karte oder bar.","gender":"m","q":"Wie viele Selbstbedienungs-Kassen gibt es?","opts":["Drei.","Eine.","Sechs."],"correct":0},{"transcript":"Hi Markus, hier ist Tom. Ich bin schon im Supermarkt, aber ich habe die Einkaufsliste zu Hause vergessen. Das Geld habe ich in der Tasche, und einen Wagen habe ich auch genommen. Brot habe ich, Käse auch. Brauchen wir noch Wein oder Obst? Ruf bitte schnell zurück, sonst entscheide ich selbst.","gender":"m","q":"Was hat Tom vergessen?","opts":["Das Geld.","Die Einkaufsliste.","Den Wagen."],"correct":1},{"transcript":"Liebe Kunden: Unser Supermarkt hat ab Montag neue Öffnungszeiten. Wir sind nicht mehr bis 20 Uhr offen, sondern bis 22 Uhr. Bis 24 Uhr können wir leider nicht öffnen, das ist zu lang für unser Team. Sonntags bleiben wir geschlossen wie bisher. Wir freuen uns auf längere Einkaufszeiten am Abend. Vielen Dank!","gender":"f","q":"Bis wann ist der Supermarkt jetzt offen?","opts":["20 Uhr.","24 Uhr.","22 Uhr."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was kaufen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Das Fest am Samstag braucht noch einen Einkaufsplan."},{"speaker":"Lisa","gender":"f","text":"Die Tasche wird zu schwer, wenn wir alles an einem Tag holen."},{"speaker":"Lukas","gender":"m","text":"Das Fleisch fürs Grillen hole ich beim Metzger. Der hat montags die frische Lieferung."},{"speaker":"Lisa","gender":"f","text":"Du kennst den Laden an der Ecke. Das wird sicher lecker."},{"speaker":"Lukas","gender":"m","text":"Sollen wir auch Chips und Snacks mitnehmen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Chips und Snacks kaufen wir nicht."},{"speaker":"Lukas","gender":"m","text":"Dienstag bist du mit den schweren Kisten dran. Nimmst du auf dem Rückweg noch etwas mit?"},{"speaker":"Lisa","gender":"f","text":"Ja. Saft und Wasser, die großen Kisten mit den Getränken."},{"speaker":"Lukas","gender":"m","text":"Und das Brot? Früh am Mittwoch ist der Bäcker noch ruhig."},{"speaker":"Lisa","gender":"f","text":"Dann holen wir Brötchen, solange sie warm sind. So schmecken sie am besten."},{"speaker":"Lukas","gender":"m","text":"Der Markt am Donnerstag ist auf dem großen Platz. Gehst du mit?"},{"speaker":"Lisa","gender":"f","text":"Ja, wegen des Salats. Die Tomaten sind dort richtig frisch."},{"speaker":"Lukas","gender":"m","text":"Brauchen wir auf der Liste auch Käse?"},{"speaker":"Lisa","gender":"f","text":"Nein. Käse brauchen wir auch keinen."},{"speaker":"Lukas","gender":"m","text":"Für den süßen Schluss am Freitag brauche ich dich. Was nimmst du mit?"},{"speaker":"Lisa","gender":"f","text":"Den Nachtisch. Kuchen und Eis kommen beide mit."},{"speaker":"Lukas","gender":"m","text":"Ich hänge den Zettel an den Kühlschrank."},{"speaker":"Lisa","gender":"f","text":"Samstag kann das Fest dann ohne Eile starten."}],"options":[{"letter":"a","text":"Fisch"},{"letter":"b","text":"Getränke"},{"letter":"c","text":"Chips und Snacks"},{"letter":"d","text":"Käse"},{"letter":"e","text":"Nachtisch"},{"letter":"f","text":"Fleisch"},{"letter":"g","text":"Gemüse für Salat"},{"letter":"h","text":"Wein"},{"letter":"i","text":"Brot und Brötchen"}],"items":[{"person":"Montag","correct":"f"},{"person":"Dienstag","correct":"b"},{"person":"Mittwoch","correct":"i"},{"person":"Donnerstag","correct":"g"},{"person":"Freitag","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, wo finde ich bitte das Mehl?"},{"speaker":"Mitarbeiter","gender":"m","text":"Im Gang 7, bei den Backsachen, neben dem Zucker."},{"speaker":"Kundin","gender":"f","text":"Welche Sorte brauche ich für Kuchen? Haben Sie Typ 550 oder Typ 1050?"},{"speaker":"Mitarbeiter","gender":"m","text":"Typ 550 ist für Brot und Typ 1050 ist sehr dunkel. Für Kuchen nehmen Sie Typ 405, das ist das feinste."},{"speaker":"Kundin","gender":"f","text":"Gut, dann nehme ich Typ 405. Vielen Dank für die Hilfe!"}],"q":"Welches Mehl?","opts":["Typ 550.","Typ 405.","Typ 1050."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, diese Erdbeeren sehen gut aus. Sind sie aus Deutschland?"},{"speaker":"Verkäufer","gender":"m","text":"Nein, heute kommen sie aus Spanien. Die deutschen Erdbeeren sind noch nicht da."},{"speaker":"Kundin","gender":"f","text":"Haben Sie auch welche aus Italien? Oder deutsche?"},{"speaker":"Verkäufer","gender":"m","text":"Italienische haben wir nicht. Deutsche Erdbeeren kommen erst im Mai. Heute nur Spanien."},{"speaker":"Kundin","gender":"f","text":"Okay, dann nehme ich trotzdem ein Kilo aus Spanien. Danke!"}],"q":"Woher kommen die Erdbeeren heute?","opts":["Deutschland.","Italien.","Spanien."],"correct":2},{"lines":[{"speaker":"Sohn","gender":"m","text":"Mama, kann ich bitte eine Schokolade kaufen? Ich habe so Lust darauf."},{"speaker":"Mutter","gender":"f","text":"Nicht heute. Du hattest gestern schon Schokolade, das reicht."},{"speaker":"Sohn","gender":"m","text":"Bitte, nur eine kleine Tafel! Oder darf ich einen Apfel?"},{"speaker":"Mutter","gender":"f","text":"Nein, keine Schokolade. Heute gibt es Obst, Apfel oder Banane, was möchtest du?"},{"speaker":"Sohn","gender":"m","text":"Dann eine Banane bitte. Die ist süß und ich mag sie gern."}],"q":"Was bekommt der Sohn?","opts":["Schokolade.","Banane.","Apfel."],"correct":1},{"lines":[{"speaker":"Kassiererin","gender":"f","text":"Das macht 47 Euro 30 bitte. Möchten Sie bar zahlen oder mit Karte?"},{"speaker":"Kunde","gender":"m","text":"Geht beides? Ich habe nur 30 Euro bar in der Tasche."},{"speaker":"Kassiererin","gender":"f","text":"Ja, beides ist möglich. Sie können bar oder mit Karte zahlen, wie Sie möchten."},{"speaker":"Kunde","gender":"m","text":"Dann Karte bitte, bar reicht heute nicht. Hier ist meine Karte."},{"speaker":"Kassiererin","gender":"f","text":"Alles klar, zahlen Sie bitte mit Karte. Einen schönen Tag noch!"}],"q":"Wie zahlt der Kunde?","opts":["Karte.","Bar.","Beides."],"correct":0},{"lines":[{"speaker":"Vater","gender":"m","text":"Wir brauchen Eier für den Kuchen. Sollen wir Bio-Eier nehmen oder normale Eier?"},{"speaker":"Mutter","gender":"f","text":"Bio-Eier sind teurer, fast das Doppelte. Normale Eier reichen doch, oder?"},{"speaker":"Vater","gender":"m","text":"Für die Kinder ist Bio besser, finde ich. Keine Eier kaufen geht nicht, wir brauchen sie."},{"speaker":"Mutter","gender":"f","text":"Okay, dann nehmen wir Bio-Eier. Zwei Schachteln, dann haben wir genug für die Woche."}],"q":"Was kaufen sie?","opts":["Bio-Eier.","Normale Eier.","Keine Eier."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Beckmann, einer Supermarkt-Leiterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Beckmann, Sie leiten den Supermarkt seit 8 Jahren. Wie wird ein Supermarkt heute geführt?"},{"speaker":"Beckmann","gender":"f","text":"Sehr anders als früher. Heute schauen wir täglich auf Verkaufs-Daten, was die Kunden wollen. Trends ändern sich schnell — Bio, vegan, glutenfrei. Wenn wir zu spät reagieren, verlieren wir Kunden an die Konkurrenz."},{"speaker":"Reporter","gender":"m","text":"Welche Produkte verkaufen sich am besten?"},{"speaker":"Beckmann","gender":"f","text":"Klassiker bleiben Klassiker — Milch, Brot, Eier. Aber Bio-Produkte wachsen am stärksten. Tiefkühlware ist immer beliebt — schnell und einfach. Süßigkeiten leider auch, viel zu viele. Aber wer entscheidet, ist der Kunde."},{"speaker":"Reporter","gender":"m","text":"Was ist die größte Herausforderung?"},{"speaker":"Beckmann","gender":"f","text":"Personal finden. Niemand will im Supermarkt arbeiten — Schichten, Wochenende, wenig Geld. Wir bezahlen über Tarif, aber trotzdem schwer. Die jungen Leute wollen Büro-Jobs, nicht Regale einräumen."},{"speaker":"Reporter","gender":"m","text":"Wie ist Diebstahl?"},{"speaker":"Beckmann","gender":"f","text":"Ja, ein Problem. Vor allem Alkohol und teure Sachen wie Kosmetik. Wir haben Kameras, Sicherheits-Leute. Trotzdem verschwinden 2-3 Prozent unserer Ware. Das ist viel Geld am Ende des Jahres."},{"speaker":"Reporter","gender":"m","text":"Wie ist die Zukunft?"},{"speaker":"Beckmann","gender":"f","text":"Online-Lieferung wächst, aber die meisten kommen noch persönlich. Selbstbedienungs-Kassen kommen mehr. Vielleicht bald komplett ohne Personal — wie in den USA. Aber Beratung wird immer gefragt sein."}],"items":[{"q":"Frau Beckmann muss schnell auf Trends reagieren.","correct":"ja"},{"q":"Bio-Produkte verkaufen sich heute besser als früher.","correct":"ja"},{"q":"Es ist einfach, neues Personal zu finden.","correct":"nein"},{"q":"Diebstahl ist kein Problem im Supermarkt.","correct":"nein"},{"q":"Die meisten Kunden kaufen heute online.","correct":"nein"}]}]};
